#!/usr/bin/env python3
"""
Command-line utility to list contents of a MIX file.
Shows the CRC (checksum), offset, and size of each file contained in the MIX archive.
Optionally uses a mix database file to identify filenames and descriptions.
"""

import struct
import sys
import zlib
import base64
import argparse
import os

def calculate_crc(buffer):
    """
    Calculate CRC using the same algorithm as the C++ implementation.
    This matches the x86 assembly version (rotate left, add value).
    """
    if not buffer or len(buffer) == 0:
        return 0
    
    crc = 0
    data = buffer
    local_length = len(data)
    
    # Calculate number of 4-byte chunks (round up by padding with zeros)
    num_chunks = (local_length + 3) >> 2
    
    # Process all chunks uniformly (remainder bytes are implicitly zero-padded)
    for i in range(num_chunks):
        chunk_start = i * 4
        bytes_available = local_length - chunk_start
        
        # Construct dword from bytes in little-endian order
        value = ((data[chunk_start] if bytes_available > 0 else 0) |
                ((data[chunk_start + 1] << 8) if bytes_available > 1 else 0) |
                ((data[chunk_start + 2] << 16) if bytes_available > 2 else 0) |
                ((data[chunk_start + 3] << 24) if bytes_available > 3 else 0))
        
        # Rotate CRC left by 1 bit
        high_bit = 1 if (crc & 0x80000000) else 0
        crc = ((crc << 1) | high_bit) & 0xFFFFFFFF
        
        # Add the 4-byte value
        crc = (crc + value) & 0xFFFFFFFF
    
    return crc

def read_mix_file(filename):
    """Read and parse a MIX file, returning a list of file entries."""
    with open(filename, 'rb') as f:
        # Read header: count (16-bit) and size (32-bit), both little-endian
        header = f.read(6)
        if len(header) != 6:
            raise ValueError("File too short to contain MIX header")
        
        count, data_size = struct.unpack('<HI', header)
        
        # Read SubBlock array: each entry has CRC (32-bit), Offset (32-bit), Size (32-bit)
        entries = []
        for i in range(count):
            subblock = f.read(12)
            if len(subblock) != 12:
                raise ValueError(f"File truncated: expected SubBlock {i+1} of {count}")
            
            crc, offset, size = struct.unpack('<III', subblock)
            entries.append({
                'index': i,
                'crc': crc,
                'offset': offset,
                'size': size
            })
        
        return entries

