def read_mix_database(filename=None):
    """
    Read the mix database file and return a dictionary mapping CRC to (filename, description).
    If filename is None, uses the embedded database.
    """
    if filename is None:
        # Use embedded database
        compressed = base64.b85decode(_EMBEDDED_DATABASE.encode('ascii'))
        data = zlib.decompress(compressed)
    else:
        # Read from file
        with open(filename, 'rb') as f:
            data = f.read()
    
    # Read header (4 bytes, but we don't use it for matching)
    if len(data) < 4:
        return {}
    
    # Parse strings
    offset = 4
    database = {}
    
    while offset < len(data):
        # Find next null byte
        null_pos = data.find(b'\x00', offset)
        if null_pos == -1:
            break
        
        string_bytes = data[offset:null_pos]
        if len(string_bytes) == 0:
            offset = null_pos + 1
            continue
        
        try:
            string = string_bytes.decode('ascii')
        except:
            offset = null_pos + 1
            continue
        
        # Check if this looks like a filename (has extension)
        if '.' in string and not string.startswith('icon:'):
            filename = string.upper()  # Match game's uppercase conversion
            filename_bytes = filename.encode('ascii')
            
            # Calculate CRC for this filename
            crc = calculate_crc(filename_bytes)
            
            # Get description (next string)
            desc_offset = null_pos + 1
            if desc_offset < len(data):
                desc_null = data.find(b'\x00', desc_offset)
                if desc_null != -1:
                    desc_bytes = data[desc_offset:desc_null]
                    try:
                        description = desc_bytes.decode('ascii')
                        database[crc] = (filename, description)
                    except:
                        pass
                    offset = desc_null + 1
                    continue
        
        offset = null_pos + 1
    
    return database

def process_mix_file(mix_filename, database):
    """Process a single MIX file and print its contents."""
    try:
        entries = read_mix_file(mix_filename)
        
        print(f"MIX file: {mix_filename}")
        print(f"Files contained: {len(entries)}\n")
        
        if database:
            print(f"{'Index':<6} {'CRC (hex)':<12} {'Offset':<10} {'Size':<10} {'Filename':<30} {'Description'}")
            print("-" * 100)
            for entry in entries:
                crc = entry['crc']
                if crc in database:
                    filename, description = database[crc]
                    print(f"{entry['index']:<6} 0x{crc:08X}  {entry['offset']:<10} {entry['size']:<10} {filename:<30} {description}")
                else:
                    print(f"{entry['index']:<6} 0x{crc:08X}  {entry['offset']:<10} {entry['size']:<10} {'(unknown)':<30}")
        else:
            print(f"{'Index':<6} {'CRC (hex)':<12} {'Offset':<10} {'Size':<10}")
            print("-" * 40)
            for entry in entries:
                print(f"{entry['index']:<6} 0x{entry['crc']:08X}  {entry['offset']:<10} {entry['size']:<10}")
        
        return True
    
    except FileNotFoundError:
        print(f"Error: File '{mix_filename}' not found", file=sys.stderr)
        return False
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        return False

def extract_from_mix_file(mix_filename, entries, extract_crc, database, outdir):
    """
    Extract every entry in a MIX archive whose CRC matches extract_crc.
    """
    matches = [e for e in entries if e.get('crc') == extract_crc]
    if not matches:
        print(f"  (extract) No match in {mix_filename} for 0x{extract_crc:08X}")
        return False

    # Derive output base name from database if possible
    out_name = None
    if database and extract_crc in database:
        out_name, _desc = database[extract_crc]
        out_name = out_name.strip()

    # SubBlock.Offset is relative to the start of the embedded data section, not BOF.
    # Layout: 6-byte FileHeader (count u16 + data_size u32) then count * 12-byte index.
    # Matches MixFileClass::SubBlock comment in MIXFILE.H and file.Seek in MIXFILE.CPP::Cache.
    count = len(entries)
    data_base = 6 + count * 12

    ok = True
    with open(mix_filename, 'rb') as f:
        for m in matches:
            idx = m.get('index', 0)
            off = m['offset']
            size = m['size']
            f.seek(data_base + off)
            data = f.read(size)
            if data is None or len(data) != size:
                print(f"  (extract) Read short for idx={idx} size={size} in {mix_filename}", file=sys.stderr)
                ok = False
                continue

            if out_name:
                # Some filenames may contain directory separators; preserve them.
                out_path = os.path.join(outdir, out_name)
            else:
                out_path = os.path.join(outdir, f"crc_{extract_crc:08X}_idx{idx}")

            parent = os.path.dirname(out_path)
            if parent:
                os.makedirs(parent, exist_ok=True)

            with open(out_path, 'wb') as outf:
                outf.write(data)

            print(f"  extracted idx={idx} 0x{extract_crc:08X} -> {out_path}")

    return ok

def main():
    parser = argparse.ArgumentParser(
        description='List contents of MIX files with CRC, offset, size, and optional filename/description lookup',
        formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument('mixfiles', nargs='+', metavar='MIXFILE',
                       help='One or more MIX files to analyze')
    parser.add_argument('-d', '--database', metavar='DATABASE',
                       help='Optional mix database file for filename/description lookup (if not provided, uses embedded database)')
    parser.add_argument('-x', '--extract', metavar='FILE_OR_CRC',
                       help='Extract a member from the MIX archives. Accepts either a hex CRC (e.g. 0x1234ABCD or 1234ABCD) or a database filename (e.g. CONQUER.MIX entry name).')
    parser.add_argument('-o', '--outdir', metavar='OUTDIR', default='.',
                       help='Output directory for extracted files (default: current directory).')
    
    args = parser.parse_args()
    
    mix_filenames = args.mixfiles
    database_filename = args.database
    extract_arg = args.extract
    outdir = args.outdir
    
    extract_crc = None
    if extract_arg:
        s = extract_arg.strip()
        # Accept hex CRC input
        if s.lower().startswith('0x'):
            extract_crc = int(s, 16)
        else:
            # Pure hex?
            is_hex = all(ch in '0123456789abcdefABCDEF' for ch in s)
            if is_hex and len(s) <= 8:
                extract_crc = int(s, 16)
            else:
                # Treat as database filename: CRC is calculated on uppercase ASCII
                extract_crc = calculate_crc(s.upper().encode('ascii'))
        print(f"Using extract target {extract_arg!r} -> CRC 0x{extract_crc:08X}\n")
    
    # Load database (use embedded if no file provided)
    database = {}
    if database_filename:
        try:
            database = read_mix_database(database_filename)
            print(f"Loaded {len(database)} entries from database file\n")
        except FileNotFoundError:
            print(f"Warning: Database file '{database_filename}' not found, using embedded database\n", file=sys.stderr)
            database = read_mix_database()  # Use embedded
        except Exception as e:
            print(f"Warning: Error loading database file: {e}, using embedded database\n", file=sys.stderr)
            database = read_mix_database()  # Use embedded
    else:
        # Use embedded database by default
        database = read_mix_database()
        print(f"Using embedded database with {len(database)} entries\n")
    
    # Process each mix file
    success_count = 0
    for i, mix_filename in enumerate(mix_filenames):
        if i > 0:
            print()  # Blank line between files
        entries = read_mix_file(mix_filename)
        if extract_crc is not None:
            if extract_from_mix_file(mix_filename, entries, extract_crc, database, outdir):
                success_count += 1
        else:
            if process_mix_file(mix_filename, database):
                success_count += 1
    
    # Exit with error if any file failed
    if success_count < len(mix_filenames):
        sys.exit(1)

if __name__ == '__main__':
    main()

